from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = []
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.blocked_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        current_date = self.Time.date()

        if self.held_symbol is not None:
            security = self.Securities.get(self.held_symbol)
            if security is not None and security.Holdings.Invested:
                expiration_date = security.Symbol.ID.Date.date()

                if current_date >= expiration_date:
                    self.blocked_entry_date = current_date
                    self._submit_exit("expiration processing")
                elif self.Time.time() >= time(15, 45):
                    previous_trading_day = self.Securities[self.spy.Symbol].Exchange.Hours.GetPreviousTradingDay(
                        expiration_date
                    ).date()

                    if current_date == previous_trading_day:
                        self._submit_exit("expiration time stop")

                self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar)

        if self.pending_signal:
            self.pending_signal = False
            self._try_enter(slice)

    def _process_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        current_time = end_time.time()

        if current_time < time(9, 31) or current_time > time(16, 0):
            return

        minute_of_day = end_time.hour * 60 + end_time.minute
        bucket_end_minutes = ((minute_of_day // 5) + 1) * 5
        bucket_end = datetime(
            end_time.year,
            end_time.month,
            end_time.day
        ) + timedelta(minutes=bucket_end_minutes)

        if self.bucket_end is None:
            self.bucket_end = bucket_end

        if bucket_end != self.bucket_end:
            self._complete_bucket()
            self.bucket_bars = []
            self.bucket_end = bucket_end

        self.bucket_bars.append(bar)

    def _complete_bucket(self):
        if len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        completed_end = self.bucket_end
        close_price = self.bucket_bars[-1].Close

        self.fast_values.append(close_price)
        self.slow_values.append(close_price)

        if len(self.fast_values) == 5 and len(self.slow_values) == 20:
            fast = sum(self.fast_values) / 5.0
            slow = sum(self.slow_values) / 20.0

            if self.previous_fast is not None and self.previous_slow is not None:
                bullish_cross = (
                    self.previous_fast <= self.previous_slow
                    and fast > slow
                )

                eligible_time = (
                    time(9, 45) <= completed_end.time() <= time(14, 30)
                )

                if bullish_cross and eligible_time:
                    self.pending_signal = True

            self.previous_fast = fast
            self.previous_slow = slow

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chain = None
        for candidate_chain in slice.OptionChains.Values:
            if candidate_chain.Symbol.Underlying == self.spy.Symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        minimum_expiration = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        selected_expiration = expirations[0]
        spy_price = self.Securities[self.spy.Symbol].Price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def _check_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        chain = None
        for candidate_chain in slice.OptionChains.Values:
            if candidate_chain.Symbol.Underlying == self.spy.Symbol:
                chain = candidate_chain
                break

        if chain is None:
            return

        contract = next(
            (contract for contract in chain if contract.Symbol == self.held_symbol),
            None
        )

        if contract is None:
            return

        if contract.BidPrice <= 0 or contract.AskPrice <= 0:
            return

        midpoint = (contract.BidPrice + contract.AskPrice) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        security = self.Securities.get(self.held_symbol)
        if security is None or not security.Holdings.Invested:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        quantity = -security.Holdings.Quantity

        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
        self.Debug("Exit submitted ({0}): {1}".format(reason, self.held_symbol))

    def _handle_unexpected_spy_position(self):
        holdings = self.Portfolio[self.spy.Symbol]

        if not holdings.Invested:
            return

        if self.equity_liquidation_ticket is not None:
            return

        self.Debug("Unexpected exercise or assignment handling: liquidating SPY equity.")
        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy.Symbol,
            -holdings.Quantity
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.entry_ticket = None
            self.Debug(
                "Entry filled: {0} at {1}".format(
                    self.held_symbol,
                    self.entry_price
                )
            )

        elif self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            self.Debug(
                "Exit filled: {0} at {1}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None

        elif (
            self.equity_liquidation_ticket is not None
            and order_event.OrderId == self.equity_liquidation_ticket.OrderId
        ):
            self.Debug(
                "Unexpected SPY equity liquidation filled at {0}.".format(
                    order_event.FillPrice
                )
            )
            self.equity_liquidation_ticket = None

