from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
                                     .Strikes(-100, 100)
                                     .Expiration(0, 365)
        )
        self.option_canonical = option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.current_chain = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_date = None
        self.expiration_block_date = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = []

    def OnData(self, slice: Slice):
        self.current_chain = None

        if slice.OptionChains.ContainsKey(self.option_canonical):
            self.current_chain = slice.OptionChains[self.option_canonical]

        self._process_minute_spy_bar(slice)
        self._process_held_position()
        self._process_expiration_rules()

    def _process_minute_spy_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        local_time = bar.End
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        bar_time = bar.Time
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        session_start = time(9, 30)
        session_end = time(16, 0)

        if not (session_start <= bar_time.time() < session_end):
            return

        date = bar_time.date()
        minute_of_day = bar_time.hour * 60 + bar_time.minute
        session_minute = minute_of_day - (9 * 60 + 30)
        bucket_minute = (session_minute // 5) * 5
        bucket_start = datetime.combine(date, session_start) + timedelta(
            minutes=bucket_minute
        )

        if self.bucket_date != date or self.bucket_start != bucket_start:
            self._finalize_five_minute_bucket()

            self.bucket_date = date
            self.bucket_start = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(bar)

    def _finalize_five_minute_bucket(self):
        if self.bucket_start is None:
            return

        bars = self.bucket_bars
        if len(bars) != 5:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        actual_times = []
        for bar in bars:
            t = bar.Time
            if t.tzinfo is not None:
                t = t.replace(tzinfo=None)
            actual_times.append(t)

        if actual_times != expected_times:
            return

        close = float(bars[-1].Close)
        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not (self.fast_window.IsReady and self.slow_window.IsReady):
            return

        current_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        previous_fast = (
            sum(self.fast_window[i] for i in range(1, 5)) / 4.0
            if self.fast_window.Count >= 5 else None
        )
        previous_slow = (
            sum(self.slow_window[i] for i in range(1, 20)) / 19.0
            if self.slow_window.Count >= 20 else None
        )

        if previous_fast is None or previous_slow is None:
            return

        bar_end = self.bucket_start + timedelta(minutes=5)
        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish_cross:
            self._try_enter_call(close, bar_end)

    def _try_enter_call(self, spy_price: float, signal_time: datetime):
        if self.entry_ticket is not None:
            if self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
        ):
                return

        if self.held_option is not None:
            holding = self.Portfolio[self.held_option]
            if holding.Invested:
                return

        if self.expiration_block_date == signal_time.date():
            return

        if self.current_chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        current_date = signal_time.date()
        eligible = []

        for contract in self.current_chain:
            expiry = contract.Expiry.date()
            if expiry >= current_date + timedelta(days=7):
                eligible.append(contract)

        if not eligible:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        expiration = min(contract.Expiry.date() for contract in eligible)

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {} strike {} expiry {}".format(
                selected.Symbol, selected.Strike, selected.Expiry.date()
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.time_stop_date = self.Securities[
                    self.held_option
                ].Symbol.ID.Date.date() - timedelta(days=1)

                self.Debug(
                    "Call entry filled: {} at {:.4f}".format(
                        self.held_option, self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Call exit filled: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
                self.time_stop_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.exit_ticket = None

    def _process_held_position(self):
        if self.held_option is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        if self.current_chain is None:
            return

        contract = None
        for candidate in self.current_chain:
            if candidate.Symbol == self.held_option:
                contract = candidate
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        if self.exit_ticket is None:
            self.exit_ticket = self.MarketOrder(
                self.held_option, -holding.Quantity
            )
            self.Debug("Profit target reached: {}".format(self.held_option))

    def _process_expiration_rules(self):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if not holding.Invested:
            return

        security = self.Securities[self.held_option]
        expiration_date = security.Symbol.ID.Date.date()
        today = self.Time.date()

        if today == expiration_date:
            self.expiration_block_date = today
            self._liquidate_held_option("expiration-day liquidation")
            return

        if (
            today == expiration_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
