from AlgorithmImports import *
from datetime import datetime, timedelta, time
from collections import defaultdict


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute, Market.USA)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute, Market.USA)
        self.option.SetFilter(lambda universe: universe.IncludeWeeklys()
                              .Strikes(-100, 100)
                              .Expiration(0, 370))

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._buckets = defaultdict(dict)
        self._previous_fast = None
        self._previous_slow = None
        self._crossover_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_on_expiration_day = False

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            if self.expiration_date is not None:
                if self.Time.date() >= self.expiration_date:
                    self._submit_exit("expiration processing")
                elif (self.Time.date() == self.expiration_date - timedelta(days=1)
                      and self.Time.time() >= time(15, 45)):
                    self._submit_exit("expiration time stop")

            if self.held_symbol is not None and self.entry_price is not None:
                self._check_profit_target(slice)

        if self._crossover_signal:
            self._crossover_signal = False
            self._try_enter(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar)

    def _process_minute_bar(self, bar: TradeBar):
        end = bar.EndTime
        if end.time() < time(9, 31) or end.time() > time(16, 0):
            return

        bucket_end_minute = ((end.minute + 4) // 5) * 5
        bucket_end = end.replace(minute=0, second=0, microsecond=0) + timedelta(
            minutes=bucket_end_minute
        )

        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return

        bucket = self._buckets[bucket_end.date(), bucket_end]
        bucket[end] = bar

        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)
        ]

        if not all(t in bucket for t in expected_times):
            return

        bars = [bucket[t] for t in expected_times]
        del self._buckets[bucket_end.date(), bucket_end]

        consolidated = TradeBar(
            self.spy,
            bucket_end - timedelta(minutes=5),
            bucket_end,
            bars[0].Open,
