        self._process_position_exit(slice)

        if self.signal_pending:
            signal_time = self.signal_time
            self.signal_pending = False
            self.signal_time = None

            if signal_time is not None:
                signal_clock = signal_time.time()
                if time(9, 45) <= signal_clock <= time(14, 30):
                    self._try_enter(slice)

    def _process_spy_minute(self, bar: TradeBar):
        local_start = bar.Time.astimezone(self.TimeZone)
        local_end = bar.EndTime.astimezone(self.TimeZone)

        if local_start.date() != local_end.date():
            return

        if local_start.time() < time(9, 30) or local_start.time() >= time(16, 0):
            return

        minutes_from_open = (local_start.hour * 60 + local_start.minute) - (9 * 60 + 30)
        if minutes_from_open < 0 or minutes_from_open % 5 != 0:
            return

        bucket_start = local_start.replace(
            second=0, microsecond=0
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = bucket_start
            self.bucket_bars = [bar]
            return

        if bucket_start != self.current_bucket_start:
            self._complete_bucket()
            self.current_bucket_start = bucket_start
            self.bucket_bars = [bar]
            return

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self._complete_bucket()
            self.current_bucket_start = None
            self.bucket_bars = []

    def _complete_bucket(self):
        if len(self.bucket_bars) != 5:
            return

        expected = self.current_bucket_start
        for bar in self.bucket_bars:
            bar_time = bar.Time.astimezone(self.TimeZone).replace(
                second=0, microsecond=0
            )
            if bar_time != expected:
                return
            expected += timedelta(minutes=1)

        close = self.bucket_bars[-1].Close

        was_ready = self.fast.IsReady and self.slow.IsReady
        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(self.bucket_bars[-1].EndTime, close)
        self.slow.Update(self.bucket_bars[-1].EndTime, close)

        if was_ready and old_fast <= old_slow:
            if self.fast.Current.Value > self.slow.Current.Value:
                self.signal_pending = True
                self.signal_time = self.bucket_bars[-1].EndTime.astimezone(
                    self.TimeZone
                )

