        if self.entry_symbol is not None:
            security = self.Securities.get(self.entry_symbol)
            if security is not None and security.Invested:
                return

        if self._ticket_is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not valid_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = valid_expirations[0]
        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price
        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_fill_price = None
        self.time_stop_date = self._previous_trading_day(selected_expiry)
        self.expiration_liquidation_date = selected_expiry

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _process_position_exit(self, slice: Slice):
        if self.entry_symbol is None or self.entry_fill_price is None:
            return

        security = self.Securities.get(self.entry_symbol)
        if security is None or not security.Invested:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.entry_symbol), None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_fill_price:
            self._cancel_open_exit()
            self.exit_ticket = self.Liquidate(self.entry_symbol)
            self.Debug("Profit target exit submitted: {0}".format(self.entry_symbol))

    def _process_expiration_liquidation(self):
        if self.entry_symbol is None:
            return

        security = self.Securities.get(self.entry_symbol)
        if security is None or not security.Invested:
            return

        today = self.Time.date()
        now = self.Time.time()

        if self.expiration_liquidation_date is not None:
            if today >= self.expiration_liquidation_date:
                if not self._ticket_is_open(self.exit_ticket):
                    self._cancel_open_exit()
                    self.exit_ticket = self.Liquidate(self.entry_symbol)
                    self.Debug("Expiration-day liquidation submitted.")
                return

        if (
            self.time_stop_date == today
            and now >= time(15, 45)
            and not self._ticket_is_open(self.exit_ticket)
        ):
            self._cancel_open_exit()
            self.exit_ticket = self.Liquidate(self.entry_symbol)
            self.Debug("Time-stop exit submitted.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.entry_fill_price = order_event.FillPrice
            self.Debug(
                "Entry filled: {0} at {1}".format(
                    self.entry_symbol, self.entry_fill_price
                )
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {0}".format(order_event.Symbol))
            self.entry_symbol = None
            self.entry_fill_price = None
            self.time_stop_date = None
            self.expiration_liquidation_date = None
            self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug("Unexpected option exercise or assignment processed.")
        self._handle_unexpected_spy_position()

    def _handle_unexpected_spy_position(self):
        holdings = self.Portfolio[self.spy]
        if holdings.Invested:
            self.Debug("Liquidating unexpected SPY equity position.")
            self.MarketOrder(self.spy, -holdings.Quantity)

    def _previous_trading_day(self, target_date: date):
        candidate = target_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def _cancel_open_exit(self):
        if self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order.")

    def _ticket_is_open(self, ticket):
        if ticket is None:
            return False
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

