        self.HandleUnexpectedSpyPosition()

        if self.held_contract is not None:
            self.EvaluateExit(slice)

        # The consolidator callback may evaluate a newly completed bar using
        # the Slice that delivered its final minute.
        if self.held_contract is not None:
            self.HandleExpirationProcessing()

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        local_time = bar.EndTime.astimezone(self.TimeZone)
        bar_date = local_time.date()
        bar_time = local_time.time()

        if local_time.weekday() >= 5:
            return

        # Ensure only regular-session, New York-aligned five-minute bars are used.
        if bar_time < time(9, 35) or bar_time > time(16, 0):
            return
        if bar_time.minute % 5 != 0:
            return

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        prior_fast = self.previous_fast
        prior_slow = self.previous_slow
        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if prior_fast is None or prior_slow is None:
            return

        eligible_time = time(9, 45) <= bar_time <= time(14, 30)
        bullish_cross = (
            prior_fast <= prior_slow and current_fast > current_slow
        )

        if not eligible_time or not bullish_cross:
            return

        if (
            self.held_contract is not None
            or self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
            or self.time_stop_submitted
            or self.expiration_liquidation_submitted
        ):
            return

        self.TryEnter()

    def TryEnter(self):
        if self.current_slice is None:
            self.Debug("Skipped selection: current Slice unavailable.")
            return

        chains = self.current_slice.OptionChains
        if self.option_symbol not in chains:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        chain = chains[self.option_symbol]
        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped selection: no expiration at least seven days away.")
            return

        selected_expiry = expiries[0]
        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price
        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiry {} strike {}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def EvaluateExit(self, slice: Slice):
        if self.held_contract is None:
            return

        security = self.Securities[self.held_contract]
        quantity = security.Holdings.Quantity
        if quantity <= 0:
            return

        local_time = self.Time.astimezone(self.TimeZone)
        expiry_date = self.held_contract.ID.Date.date()

        if local_time.date() >= expiry_date:
            self.SubmitExit("expiration processing")
            return

        if (
            local_time.date() == expiry_date - timedelta(days=1)
            and local_time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration time stop")
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self.held_contract not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return
        if quote.Bid.Close <= 0 or quote.Ask.Close <= 0:
            return

        midpoint = (quote.Bid.Close + quote.Ask.Close) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity <= 0:
            return

        if reason == "expiration processing":
            self.expiration_liquidation_submitted = True
        elif reason == "expiration time stop":
            self.time_stop_submitted = True

        self.CancelOpenExitOrder()
        self.exit_ticket = self.MarketOrder(
            self.held_contract, -quantity, tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_contract, reason))

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            self.exit_ticket.Cancel("Replaced by higher-priority liquidation")

    def HandleExpirationProcessing(self):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.SubmitExit("expiration processing")

    def HandleUnexpectedSpyPosition(self):
        holdings = self.Portfolio[self.spy]
        if holdings.Invested:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.Liquidate(self.spy, tag="Unexpected exercise or assignment")
            self.expiration_liquidation_submitted = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if self.entry_ticket is not None and (
                order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.time_stop_submitted = False
                self.expiration_liquidation_submitted = False
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_contract, self.entry_price
                    )
                )

            elif self.exit_ticket is not None and (
                order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Exit filled: {} at {}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_contract = None
                    self.entry_price = None
                    self.time_stop_submitted = False
                    self.expiration_liquidation_submitted = False

        elif order_event.Status == OrderStatus.Canceled:
            if self.entry_ticket is not None and (
                order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_ticket = None
            if self.exit_ticket is not None and (
                order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.exit_ticket = None

