            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        )
        self.spy_symbol = self.spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(lambda universe: universe.Strikes(-200, 200).Expiration(0, 730))

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.minute_bars = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_liquidated_dates = set()

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()

        if self.held_option is not None:
            if current_date >= self.held_option.ID.Date.date():
                if current_date not in self.expiration_liquidated_dates:
                    self.Debug(
                        f"Expiration liquidation: {self.held_option} at {self.Time}"
                    )
                    self._submit_exit("expiration processing")
                    self.expiration_liquidated_dates.add(current_date)
            else:
                self._evaluate_time_stop()
                self._evaluate_profit_target(slice)

        completed_bar = self._build_five_minute_bar(slice)
        if completed_bar is None:
            return

        if self.held_option is not None or self._entry_order_open():
            return

        bar_end = completed_bar.EndTime
        if time(9, 45) <= bar_end.time() <= time(14, 30):
            self._update_averages_and_check_entry(completed_bar, slice)

    def _build_five_minute_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy_symbol):
            return None

        minute_bar = slice.Bars[self.spy_symbol]
        local_end = minute_bar.EndTime
        if local_end.tzinfo is None:
            local_end = self.TimeZone.ConvertFromUtc(
                minute_bar.EndTime.replace(tzinfo=DateTime.UtcNow.tzinfo)
            )

        local_date = self.Time.date()
        bar_time = minute_bar.EndTime.time()

        if local_date != self.Time.date():
            return None
        if bar_time < time(9, 31) or bar_time > time(16, 0):
            return None

        minute = minute_bar.EndTime.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = datetime(
            minute_bar.EndTime.year,
            minute_bar.EndTime.month,
            minute_bar.EndTime.day,
            minute_bar.EndTime.hour,
            bucket_end_minute,
            tzinfo=minute_bar.EndTime.tzinfo
        )

        key = bucket_end
        bucket = self.minute_bars.setdefault(key, [])
        if not bucket or bucket[-1].EndTime != minute_bar.EndTime:
            bucket.append(minute_bar)

        if len(bucket) < 5:
            return None

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]
        actual = [bar.EndTime for bar in bucket[-5:]]
        del self.minute_bars[key]

        if actual != expected:
            return None

        bars = bucket[-5:]
        return TradeBar(
            symbol=self.spy_symbol,
            time=bars[0].Time,
            period=timedelta(minutes=5),
            open=bars[0].Open,
            high=max(bar.High for bar in bars),
            low=min(bar.Low for bar in bars),
            close=bars[-1].Close,
            volume=sum(bar.Volume for bar in bars)
        )

    def _update_averages_and_check_entry(self, bar: TradeBar, slice: Slice):
        previous_fast = self.fast_window[0] if self.fast_window.IsReady else None
        previous_slow = self.slow_window[0] if self.slow_window.IsReady else None

        self.fast_window.Add(float(bar.Close))
        self.slow_window.Add(float(bar.Close))

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return
        if previous_fast is None or previous_slow is None:
            return

        current_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        if previous_fast <= previous_slow and current_fast > current_slow:
            self._enter_call(slice, float(bar.Close))

    def _enter_call(self, slice: Slice, spy_price: float):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"Skipped entry: no option chain at {self.Time}")
            return

        chain = slice.OptionChains[self.option_symbol]
        algorithm_date = self.Time.date()

        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - algorithm_date).days >= 7
        ]

        if not eligible:
            self.Debug(f"Skipped entry: no eligible expiration at {self.Time}")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        threshold = spy_price * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug(f"Skipped entry: no qualifying call strike at {self.Time}")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"Entry submitted: {selected.Symbol} at {self.Time}")

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return
        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.New
        ):
            return
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            return

        contract = next(
            (c for c in slice.OptionChains[self.option_symbol]
             if c.Symbol == self.held_option),
            None
        )
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target")

    def _evaluate_time_stop(self):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        preceding_date = expiry_date - timedelta(days=1)
        while preceding_date.weekday() >= 5:
            preceding_date -= timedelta(days=1)

        if self.Time.date() == preceding_date and self.Time.time() >= time(15, 45):
            self._submit_exit("time stop")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.New
        ):
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.New
        ):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -int(self.Portfolio[self.held_option].Quantity)
        )
        self.Debug(f"Exit submitted ({reason}): {self.held_option} at {self.Time}")

    def _entry_order_open(self):
        return self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.New
        )

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy_symbol]
        if holding.Invested:
            self.Debug(
                f"Unexpected SPY equity position detected; liquidating at {self.Time}"
            )
            self.Liquidate(self.spy_symbol)

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Type == OrderType.OptionExercise:
            self.Debug(f"Unexpected option exercise or assignment: {order_event}")
            self.Liquidate(self.spy_symbol)
            return

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_option}, "
                    f"price {self.entry_price} at {self.Time}"
                )
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order.Symbol} at {self.Time}")
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.exit_ticket = None

